add_action( 'init', 'perfectpixel_rename_endpoint_titles_setup' );

function perfectpixel_rename_endpoint_titles_setup() {
	foreach ( array( 'orders', 'view-order', 'downloads', 'edit-address', 'edit-account', 'payment-methods', 'add-payment-method' ) as $endpoint ) {
		add_filter( 'woocommerce_endpoint_' . $endpoint . '_title', 'perfectpixel_rename_endpoint_title', 20, 2 );
	}
}

function perfectpixel_rename_endpoint_title( $title, $endpoint ) {
	foreach ( explode( '|', '{{account_endpoint_titles}}' ) as $pair ) {
		$parts = array_map( 'trim', explode( '=', $pair, 2 ) );
		if ( 2 === count( $parts ) && $parts[0] === $endpoint && '' !== $parts[1] ) {
			return $parts[1];
		}
	}
	return $title;
}
